-- Company walls in the database (generated by src/scripts/companyWallsSql.ts).

CREATE OR REPLACE FUNCTION "mq_wall_Department"() RETURNS trigger AS $$
DECLARE c TEXT;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW."companyId" IS DISTINCT FROM OLD."companyId" THEN
    RAISE EXCEPTION 'metriq company wall: a Department row cannot move to another company' USING ERRCODE = 'P0420';
  END IF;
  IF NEW."companyId" IS NULL OR NEW."companyId" = '' THEN
    NULL;
    NEW."companyId" := COALESCE(c, 'company-1');
    c := NULL;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS "Department_company_wall" ON "Department";
CREATE TRIGGER "Department_company_wall" BEFORE INSERT OR UPDATE ON "Department" FOR EACH ROW EXECUTE FUNCTION "mq_wall_Department"();

CREATE OR REPLACE FUNCTION "mq_wall_SubDepartment"() RETURNS trigger AS $$
DECLARE c TEXT;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW."companyId" IS DISTINCT FROM OLD."companyId" THEN
    RAISE EXCEPTION 'metriq company wall: a SubDepartment row cannot move to another company' USING ERRCODE = 'P0420';
  END IF;
  IF NEW."companyId" IS NULL OR NEW."companyId" = '' THEN
    IF c IS NULL AND NEW."departmentId" IS NOT NULL THEN SELECT "companyId" INTO c FROM "Department" WHERE "id" = NEW."departmentId"; END IF;
    NEW."companyId" := COALESCE(c, 'company-1');
    c := NULL;
  END IF;
  IF NEW."departmentId" IS NOT NULL AND (TG_OP = 'INSERT' OR NEW."departmentId" IS DISTINCT FROM OLD."departmentId") THEN
    SELECT "companyId" INTO c FROM "Department" WHERE "id" = NEW."departmentId";
    IF c IS NOT NULL AND c <> NEW."companyId" THEN RAISE EXCEPTION 'metriq company wall: SubDepartment.departmentId points at another company' USING ERRCODE = 'P0420'; END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS "SubDepartment_company_wall" ON "SubDepartment";
CREATE TRIGGER "SubDepartment_company_wall" BEFORE INSERT OR UPDATE ON "SubDepartment" FOR EACH ROW EXECUTE FUNCTION "mq_wall_SubDepartment"();

